input.script:
() => {
  // Try to find any translation-related information on the page
  const title = document.title;
  const url = window.location.href;
  const bodyText = document.body.innerText.substring(0, 500);
  return {
    title: title,
    url: url,
    bodyText: bodyText,
    hasCaptcha: !!document.querySelector('input[type="checkbox"]'),
    captchaLabel: document.querySelector('input[type="checkbox"]')?.getAttribute('aria-label')
  };
}

